from collections import deque, Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]!=0 and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            sh,sw=r1-r0+1,c1-c0+1
            if sh==sw and sh>=3 and sh%2==1 and len(cells)==sh*sw:
                cy,cx=(r0+r1)//2,(c0+c1)//2
                comps.append((r0,r1,c0,c1,cy,cx,grid[cy][cx]))
    if not comps:
        return out
    counts=Counter(t[6] for t in comps)
    base=counts.most_common(1)[0][0]
    byrow={}
    bycol={}
    for obj in comps:
        r0,r1,c0,c1,cy,cx,color=obj
        if color==base:
            continue
        byrow.setdefault(cy,[]).append(obj)
        bycol.setdefault(cx,[]).append(obj)
    for objs in byrow.values():
        objs.sort(key=lambda o:o[5])
        for a,b in zip(objs,objs[1:]):
            if a[6]==b[6]:
                for x in range(a[3]+1,b[2]): out[a[4]][x]=a[6]
    for objs in bycol.values():
